{'code': "from qgis.PyQt.QtWidgets import QAction, QMenu
mw = iface.mainWindow()
target = mw.findChild(QAction, 'mActionShowRasterCalculator')
found = []
def walk(m, path):
    for act in m.actions():
        if act is target:
            found.append(path)
        sub = act.menu()
        if sub:
            walk(sub, path + [sub.title()])
for act in mw.menuBar().actions():
    sub = act.menu()
    if sub:
        walk(sub, [sub.title()])
